-- PREFLIGHT 331 (duplicar paquete armado) — UNA sola consulta, SOLO LECTURA. Correr ANTES de la 331.
select orden, control, observado, esperado, estado from (
  select 1 as orden, 'Existen las 7 tablas del paquete armado' as control,
         (select count(*) from unnest(array['armado_paquetes','armado_vuelos','armado_empaquetados','armado_hoteles','armado_servicios','armado_paquete_destinos_aereos','salidas_dinamicas']) t where to_regclass('public.' || t) is not null)::text as observado,
         '7' as esperado,
         case when (select count(*) from unnest(array['armado_paquetes','armado_vuelos','armado_empaquetados','armado_hoteles','armado_servicios','armado_paquete_destinos_aereos','salidas_dinamicas']) t where to_regclass('public.' || t) is not null) = 7 then 'OK' else 'REVISAR' end as estado
  union all select 2, 'Existe mi_rol()', (to_regprocedure('public.mi_rol()') is not null)::text, 'true', case when to_regprocedure('public.mi_rol()') is not null then 'OK' else 'REVISAR' end
  union all select 3, 'La función aún NO existe (la crea la 331)', (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'duplicar_paquete_armado')::text, '0',
         case when (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'duplicar_paquete_armado') = 0 then 'OK' else 'REVISAR' end
  union all select 4, 'Columnas que la función copia en la cabecera (28 esperadas)',
         (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'armado_paquetes' and column_name = any(array['nombre','tipo','noches','destino_id','fecha_compra_inicio','fecha_compra_fin','fecha_viaje_inicio','fecha_viaje_fin','pct_mk','pvp_infante_fijo','impuesto_tipo','impuesto_fijo','moneda','imagen_url','notas','condicion_pago_tipo','condicion_pago_pct_inicial','condicion_pago_dias_saldo','restriccion_comercial','programa_incluye','programa_no_incluye','programa_tarifas_especiales','programa_condiciones_comerciales','destinos_aereos_alternativos','modo_oferta','trm_oferta','moneda_publicacion','activo']))::text,
         '28',
         case when (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'armado_paquetes' and column_name = any(array['nombre','tipo','noches','destino_id','fecha_compra_inicio','fecha_compra_fin','fecha_viaje_inicio','fecha_viaje_fin','pct_mk','pvp_infante_fijo','impuesto_tipo','impuesto_fijo','moneda','imagen_url','notas','condicion_pago_tipo','condicion_pago_pct_inicial','condicion_pago_dias_saldo','restriccion_comercial','programa_incluye','programa_no_incluye','programa_tarifas_especiales','programa_condiciones_comerciales','destinos_aereos_alternativos','modo_oferta','trm_oferta','moneda_publicacion','activo'])) = 28 then 'OK' else 'REVISAR' end
  union all select 5, 'Columnas que la función copia en salidas_dinamicas (21 esperadas)',
         (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'salidas_dinamicas' and column_name = any(array['paquete_id','aerolinea','ruta','origen','fecha_ida','fecha_regreso','hora_salida_ida','hora_llegada_ida','hora_salida_reg','hora_llegada_reg','valor_tiquete','aplica_mk','ta','fee_infante','compra_inicio','compra_fin','activo','notas','orden','empaquetado_id','moneda']))::text,
         '21',
         case when (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'salidas_dinamicas' and column_name = any(array['paquete_id','aerolinea','ruta','origen','fecha_ida','fecha_regreso','hora_salida_ida','hora_llegada_ida','hora_salida_reg','hora_llegada_reg','valor_tiquete','aplica_mk','ta','fee_infante','compra_inicio','compra_fin','activo','notas','orden','empaquetado_id','moneda'])) = 21 then 'OK' else 'REVISAR' end
  union all select 6, 'Paquetes armados existentes (anotar; la 331 no los toca)', (select count(*) from public.armado_paquetes)::text, 'anotar', 'INFO'
) r order by orden;
